String fn0(List<String> p0, String p1) {
  if (p0.isEmpty) {
    return '$p1: (empty)';
  }

  final entries = <List<dynamic>>[];

  for (final item in p0) {
    final parts = item.split(':');
    entries.add([
      parts[0],
      int.parse(parts[1]),
      int.parse(parts[2]),
      int.parse(parts[3]),
    ]);
  }

  entries.sort((a, b) {
    final first = (b[1] as int).compareTo(a[1] as int);
    if (first != 0) return first;

    final second = (a[2] as int).compareTo(b[2] as int);
    if (second != 0) return second;

    return (b[3] as int).compareTo(a[3] as int);
  });

  final buffer = StringBuffer();
  for (var i = 0; i < entries.length; i++) {
    if (i != 0) {
      buffer.write(' ');
    }
    buffer.write('${i + 1}.${entries[i][0]}');
  }

  return '$p1: $buffer';
}

bool fn0(int p0, String p1, int p2) {
  var value = p0;

  for (var i = 0; i < p1.length; i++) {
    final character = p1[i];

    if (character == 'P') {
      value++;
      if (value > p2) return false;
    } else if (character == 'U') {
      value--;
      if (value < 0) return false;
    } else if (character != 'D') {
      return false;
    }
  }

  return true;
}
